INSERT INTO posts (title, slug, excerpt, content, cover_image_url, author_id, category, tags, read_time_minutes, is_published, published_at) VALUES
('Arquitectura de un carrito persistente', 'arquitectura-carrito-persistente', 'Cómo combinar estado optimista, API, sesión anónima y validación de cupones sin romper la experiencia.', '<h2>Estado local y backend</h2><p>Un carrito útil debe responder al instante y, al mismo tiempo, conservar los datos cuando la persona vuelve más tarde. Para conseguirlo conviene usar estado optimista en la interfaz y confirmar cada acción contra el backend.</p><p>La sesión anónima permite añadir cursos antes de iniciar sesión. Después, el backend puede asociar el pedido al usuario autenticado sin perder el contenido del carrito.</p><h2>Cupones y totales</h2><p>El subtotal, el descuento y el total deben recalcularse siempre en servidor. El frontend puede mostrar una estimación, pero la base de datos conserva las reglas reales de negocio.</p><p>También es importante mostrar estados claros: añadido, quitado, actualizando, error y carrito vacío. Esa microinteracción evita la sensación de lentitud.</p><h2>Conclusión</h2><p>Un carrito profesional no es solo un array de cursos. Es una pieza central que conecta catálogo, usuario, cupones, pedidos y confianza.</p>', 'https://images.unsplash.com/photo-1556742502-ec7c0e9f34b1?auto=format&fit=crop&w=1200&q=82', 2, 'Ecommerce', JSON_ARRAY('carrito', 'ecommerce', 'ux'), 7, TRUE, NOW()),
('Roles en una plataforma educativa', 'roles-plataforma-educativa', 'Admin, editor, cliente y demo necesitan permisos distintos para que el producto sea seguro y defendible.', '<h2>Separar responsabilidades</h2><p>Los roles reducen errores porque cada usuario ve solo las acciones que necesita. Un administrador gestiona usuarios, pedidos y cupones. Un editor trabaja sobre cursos. Un cliente compra o consulta su espacio personal. Una cuenta demo navega sin modificar datos críticos.</p><p>Esta separación también ayuda en una defensa técnica: permite explicar quién puede cambiar qué y por qué.</p><h2>Permisos en backend</h2><p>Ocultar botones en frontend no es suficiente. Cada endpoint debe validar el rol antes de tocar la base de datos. Así se evitan cambios no autorizados aunque alguien llame a la API directamente.</p><p>Los mensajes de error deben ser claros sin filtrar información sensible.</p><h2>Conclusión</h2><p>Un sistema de roles sencillo, aplicado de forma consistente, hace que una plataforma beta parezca mucho más seria.</p>', 'https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&w=1200&q=82', 3, 'Backend', JSON_ARRAY('roles', 'seguridad', 'backend'), 8, TRUE, NOW()),
('Diseñar un espacio personal útil', 'disenar-espacio-personal-util', 'Pedidos, cursos, favoritos y cupones deben convivir en una zona limpia y fácil de consultar.', '<h2>Priorizar información</h2><p>El espacio personal debe responder rápido a cuatro preguntas: quién soy, qué cursos tengo, qué pedidos existen y qué ventajas puedo usar. Si todo aparece con la misma importancia, la pantalla se vuelve pesada.</p><p>Una buena estructura combina resumen, accesos directos y módulos concretos. Las tarjetas funcionan bien para métricas, pero las listas necesitan espacio para leer títulos, fechas y estados.</p><h2>Responsive y claridad</h2><p>En móvil, los bloques deben apilarse sin perder jerarquía. Botones grandes, textos cortos y separaciones constantes hacen que la cuenta se sienta más estable.</p><p>También conviene evitar mensajes inventados. Si una función está en beta, se explica como beta; si no hay datos, se muestra un estado vacío honesto.</p><h2>Conclusión</h2><p>Una cuenta bien diseñada convierte el producto en algo que se puede usar más de una vez.</p>', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=1200&q=82', 4, 'UX', JSON_ARRAY('cuenta', 'dashboard', 'ux'), 8, TRUE, NOW()),
('Cómo plantear una beta realista', 'plantear-beta-realista', 'Una beta puede vender la idea sin simular pagos reales ni prometer funciones que aún no existen.', '<h2>Transparencia de producto</h2><p>Una beta no tiene que parecer incompleta si comunica bien sus límites. Puede tener catálogo, carrito, roles, administración y emails, pero debe dejar claro qué partes aún no procesan operaciones reales.</p><p>El checkout es un buen ejemplo: se puede enseñar el resumen y validar el flujo, pero si no hay pasarela conectada no debe crear pedidos falsos.</p><h2>Confianza y defensa</h2><p>Ser honesto mejora la percepción técnica. Explicar que una compra no se procesa evita datos incorrectos en pedidos, inscripciones y métricas.</p><p>La beta puede recoger interés con newsletters, favoritos y navegación completa mientras se prepara la integración de pago.</p><h2>Conclusión</h2><p>Una beta sólida no finge producción: muestra una base preparada para crecer.</p>', 'https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=1200&q=82', 1, 'Producto', JSON_ARRAY('beta', 'producto', 'checkout'), 7, TRUE, NOW()),
('Imágenes coherentes para cursos y blog', 'imagenes-coherentes-cursos-blog', 'Las imágenes de portada ayudan a entender qué se vende antes de leer el detalle completo.', '<h2>La portada también informa</h2><p>Una imagen no debe ser solo decoración. En cursos y artículos, la portada debe anticipar tecnología, contexto o tipo de proyecto. Si el curso trata de cloud, una imagen de infraestructura comunica mejor que una foto genérica.</p><p>La coherencia visual reduce confusión y hace que el catálogo se pueda escanear con más facilidad.</p><h2>Fallbacks y rendimiento</h2><p>Como las imágenes externas pueden fallar, conviene tener un fallback estable. También hay que usar object-fit, tamaños fijos y carga diferida para evitar saltos de layout.</p><p>En tarjetas, la imagen debe rellenar el espacio sin deformarse ni ocultar información crítica.</p><h2>Conclusión</h2><p>Un catálogo con imágenes cuidadas se percibe más profesional y ayuda a decidir más rápido.</p>', 'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1200&q=82', 4, 'Diseño', JSON_ARRAY('imagenes', 'catalogo', 'blog'), 7, TRUE, NOW()),
('Sincronizar administración y catálogo', 'sincronizar-administracion-catalogo', 'Cuando un editor cambia un curso, la API, el listado y la web pública deben refrescarse con datos actuales.', '<h2>Una sola fuente de verdad</h2><p>El panel de administración debe trabajar contra la base de datos real. Crear, editar o eliminar cursos solo es útil si después el catálogo público consulta esa misma fuente y no una copia antigua.</p><p>En aplicaciones estáticas, el listado puede refrescarse en cliente contra la API para mostrar cambios recientes sin esperar a un nuevo build.</p><h2>Feedback inmediato</h2><p>Después de guardar un curso, el panel debe recargar el listado, mantener estados claros y evitar que el usuario dude si la acción se aplicó. Los botones de actualizar y los mensajes de éxito ayudan, pero lo importante es que los datos vuelvan desde backend.</p><p>También es recomendable añadir marcas de tiempo a las peticiones administrativas para evitar caché en pruebas.</p><h2>Conclusión</h2><p>Administrar contenido en tiempo real exige endpoints consistentes, permisos correctos y refresco visible en la interfaz.</p>', 'https://images.unsplash.com/photo-1556075798-4825dfaaf498?auto=format&fit=crop&w=1200&q=82', 3, 'DevOps', JSON_ARRAY('admin', 'api', 'catalogo'), 8, TRUE, NOW())
